const input=$json.body??$json;
const text=v=>v===null||v===undefined?'':String(v).trim();
const bool=v=>typeof v==='boolean'?v:['true','1','yes','on'].includes(text(v).toLowerCase());

const clinic_name=text(input.clinic_name);
const window_start_hours=Number(input.window_start_hours??20);
const window_end_hours=Number(input.window_end_hours??28);
const response_deadline_hours=Number(input.response_deadline_hours??12);
const channel=text(input.channel||'whatsapp').toLowerCase();
const limit=Number(input.limit??100);
const webhook_base_url=text(input.webhook_base_url||'http://localhost:5678/webhook').replace(/\/+$/,'');
const confirm_run=bool(input.confirm_run);

const errors=[];
if(!clinic_name)errors.push({field:'clinic_name',message:'نام کلینیک الزامی است.'});
if(!Number.isInteger(window_start_hours)||window_start_hours<0||window_start_hours>720)errors.push({field:'window_start_hours',message:'بازه شروع معتبر نیست.'});
if(!Number.isInteger(window_end_hours)||window_end_hours<1||window_end_hours>720||window_end_hours<=window_start_hours)errors.push({field:'window_end_hours',message:'بازه پایان باید از شروع بزرگ‌تر باشد.'});
if(!Number.isInteger(response_deadline_hours)||response_deadline_hours<1||response_deadline_hours>168)errors.push({field:'response_deadline_hours',message:'مهلت پاسخ معتبر نیست.'});
if(!['whatsapp','sms','email','phone','web_push','in_app'].includes(channel))errors.push({field:'channel',message:'کانال معتبر نیست.'});
if(!Number.isInteger(limit)||limit<1||limit>500)errors.push({field:'limit',message:'Limit معتبر نیست.'});
if(!/^https?:\/\/.+/i.test(webhook_base_url))errors.push({field:'webhook_base_url',message:'آدرس Webhook معتبر نیست.'});
if(confirm_run!==true)errors.push({field:'confirm_run',message:'اجرای فرایند باید تأیید شود.'});

return [{json:{
 clinic_name,window_start_hours,window_end_hours,response_deadline_hours,
 channel,limit,webhook_base_url,
 generate_url:`${webhook_base_url}/clinic/appointments/generate-confirmations`,
 queue_url:`${webhook_base_url}/clinic/communications/messages/queue`,
 confirm_run,validation_status:errors.length?'invalid':'valid',errors
}}];

const response=$json??{};
const requests=Array.isArray(response.confirmation_requests)?response.confirmation_requests:[];
const config=$('Normalize and Validate Confirmation Messaging').first().json;

if(!requests.length){
  return [{json:{
    success:true,
    has_confirmation:false,
    result:response.result||'no_confirmation_requests',
    clinic_name:config.clinic_name,
    generated_count:Number(response.confirmation_request_count||0),
    queued_count:0
  }}];
}

return requests.map(item=>({json:{
  ...item,
  has_confirmation:true,
  clinic_name:config.clinic_name,
  webhook_base_url:config.webhook_base_url,
  queue_url:config.queue_url
}}));

const original=$('Build Appointment Confirmation Message').item.json;
return [{json:{
  success:$json.success===true,
  result:$json.result||'queue_result_unknown',
  confirmation_request_id:original.confirmation_request_id,
  appointment_id:original.appointment_id,
  outbound_message_id:$json.outbound_message_id??null,
  message_status:$json.message_status??null,
  permission_decision:$json.permission_decision??null,
  next_action:$json.next_action??null
}}];
